import RNA, random, math, sys

target='...((((..(((((.....)))))..(((((...)))))..(((((.....)))))..(((((...)))))..(((((.....)))))..(((((.....))))).((((((((((((((((((((((((((((......))))).(((((.............((((.........................................)))).............)))))(((((....))))).)))))))))))))))))))))))..(((((.....)))))..(((((.....)))))..(((((.....)))))..(((((.....)))))..(((((....)))))..(((((.....))))).))))...'
n=len(target)
stack=[]; pair=[-1]*n
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pair[i]=j; pair[j]=i

def fold(s):
    fc=RNA.fold_compound(s)
    ss,mfe=fc.mfe(); return ss,mfe

def bpset(ss):
    st=[]; bps=set()
    for i,c in enumerate(ss):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); bps.add((min(i,j),max(i,j)))
    return bps

tbp=bpset(target)

# structured init: all GC pairs, loops filled with stable motifs
def init_seq():
    s=['A']*n
    for i in range(n):
        if pair[i]!=-1 and i<pair[i]:
            s[i]='G'; s[pair[i]]='C'
    # hairpin loops - fill with motifs
    # loop regions: identify hairpin loop spans
    spans=[]
    for i in range(n):
        if target[i]=='(' and pair[i]-i>2:
            inner=target[i+1:pair[i]]
            if '(' not in inner and ')' not in inner:
                spans.append((i+1,pair[i]))
    # fill 5-loops with GAAAA... actually GAAA is 4. For 5-loop use GAABA? use GAAAA? GNRA family.
    for (a,b) in spans:
        L=b-a
        if L==5:
            s[a]='G'; s[a+1]='A'; s[a+2]='A'; s[a+3]='A'; s[a+4]='A'  # GAAAA
        elif L==4:
            s[a]='G'; s[a+1]='A'; s[a+2]='A'; s[a+3]='A'
        elif L==3:
            s[a]='G'; s[a+1]='A'; s[a+2]='A'
        elif L==6:
            s[a]='G'; s[a+1]='A'; s[a+2]='A'; s[a+3]='A'; s[a+4]='A'; s[a+5]='A'
        elif L==41:
            # big internal loop - fill with A (unpaired)
            for k in range(a,b): s[k]='A'
    return ''.join(s)

s=init_seq()
ss,mfe=fold(s)
d=RNA.bp_distance(ss,target)
print('init dist',d,'mfe',mfe, file=sys.stderr)
print(ss, file=sys.stderr)
